Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
bpf: reject negative CO-RE accessor indices in
 bpf_core_parse_spec()

CO-RE accessor strings are colon-separated indices that describe a path
from a root BTF type to a target field, e.g. "0:1:2" walks through
nested struct members. bpf_core_parse_spec() parses each component with
sscanf("%d"), so negative values like -1 are silently accepted.  The
subsequent bounds checks (access_idx >= btf_vlen(t)) only guard the
upper bound and always pass for negative values because C integer
promotion converts the __u16 btf_vlen result to int, making the
comparison (int)(-1) >= (int)(N) false for any positive N.

When -1 reaches btf_member_bit_offset() it gets cast to u32 0xffffffff,
producing an out-of-bounds read far past the members array.  A crafted
BPF program with a negative CO-RE accessor on any struct that exists in
vmlinux BTF (e.g. task_struct) crashes the kernel deterministically
during BPF_PROG_LOAD on any system with CONFIG_DEBUG_INFO_BTF=y
(default on major distributions).  The bug is reachable with CAP_BPF:

 BUG: unable to handle page fault for address: ffffed11818b6626
 #PF: supervisor read access in kernel mode
 #PF: error_code(0x0000) - not-present page
 Oops: Oops: 0000 [#1] SMP KASAN NOPTI
 CPU: 0 UID: 0 PID: 85 Comm: poc Not tainted 7.0.0-rc6 #18 PREEMPT(full)
 RIP: 0010:bpf_core_parse_spec (tools/lib/bpf/relo_core.c:354)
 RAX: 00000000ffffffff
 Call Trace:
  <TASK>
  bpf_core_calc_relo_insn (tools/lib/bpf/relo_core.c:1321)
  bpf_core_apply (kernel/bpf/btf.c:9507)
  check_core_relo (kernel/bpf/verifier.c:19475)
  bpf_check (kernel/bpf/verifier.c:26031)
  bpf_prog_load (kernel/bpf/syscall.c:3089)
  __sys_bpf (kernel/bpf/syscall.c:6228)
  </TASK>

CO-RE accessor indices are inherently non-negative (struct member index,
array element index, or enumerator index), so reject them immediately
after parsing.

Fixes: ddc7c3042614 ("libbpf: implement BPF CO-RE offset relocation algorithm")
Reported-by: Xiang Mei <xmei5@asu.edu>
Signed-off-by: Weiming Shi <bestswngs@gmail.com>
Reviewed-by: Emil Tsalapatis <emil@etsalapatis.com>
Acked-by: Paul Chaignon <paul.chaignon@gmail.com>
Link: https://lore.kernel.org/r/20260404161221.961828-2-bestswngs@gmail.com
Signed-off-by: Alexei Starovoitov <ast@kernel.org>

Here is the root cause:
Negative CO-RE accessor indices are not rejected after parsing with sscanf("%d"), and the subsequent bounds check only guards the upper bound (access_idx >= btf_vlen(t)), allowing negative values to pass due to integer promotion. This leads to out-of-bounds reads when negative index is used as an offset into BTF members.

Here is the patch:
  */
 int bpf_core_parse_spec(const char *prog_name, const struct btf *btf,
 			const struct bpf_core_relo *relo,
 			struct bpf_core_spec *spec)
 {
 	int access_idx, parsed_len, i;
 	struct bpf_core_accessor *acc;
 	const struct btf_type *t;
 	const char *name, *spec_str;
 	__u32 id, name_off;
 	__s64 sz;

 	spec_str = btf__name_by_offset(btf, relo->access_str_off);
 	if (str_is_empty(spec_str) || *spec_str == ':')
 		return -EINVAL;

 	memset(spec, 0, sizeof(*spec));
 	spec->btf = btf;
 	spec->root_type_id = relo->type_id;
 	spec->relo_kind = relo->kind;

 	/* type-based relocations don't have a field access string */
 	if (core_relo_is_type_based(relo->kind)) {
 		if (strcmp(spec_str, "0"))
 			return -EINVAL;
 		return 0;
 	}

 	/* parse spec_str="0:1:2:3:4" into array raw_spec=[0, 1, 2, 3, 4] */
 	while (*spec_str) {
 		if (*spec_str == ':')
 			++spec_str;
 		if (sscanf(spec_str, "%d%n", &access_idx, &parsed_len) != 1)
 			return -EINVAL;
+		if (access_idx < 0)
+			return -EINVAL;
 		if (spec->raw_len == BPF_CORE_SPEC_MAX_LEN)
 			return -E2BIG;
 		spec_str += parsed_len;
 		spec->raw_spec[spec->raw_len++] = access_idx;
 	}

 	if (spec->raw_len == 0)
 		return -EINVAL;

 	t = skip_mods_and_typedefs(btf, relo->type_id, &id);
 	if (!t)
 		return -EINVAL;

 	access_idx = spec->raw_spec[0];
 	acc = &spec->spec[0];
 	acc->type_id = id;
 	acc->idx = access_idx;
 	spec->len++;

 	if (core_relo_is_enumval_based(relo->kind)) {
 		if (!btf_is_any_enum(t) || spec->raw_len > 1 || access_idx >= btf_vlen(t))
 			return -EINVAL;

 		/* record enumerator name in a first accessor */
 		name_off = btf_is_enum(t) ? btf_enum(t)[access_idx].name_off
 					  : btf_enum64(t)[access_idx].name_off;
 		acc->name = btf__name_by_offset(btf, name_off);
 		return 0;
 	}

 	if (!core_relo_is_field_based(relo->kind))
 		return -EINVAL;

 	sz = btf__resolve_size(btf, id);
 	if (sz < 0)
 		return sz;
 	spec->bit_offset = access_idx * sz * 8;

 	for (i = 1; i < spec->raw_len; i++) {
 		t = skip_mods_and_typedefs(btf, id, &id);
 		if (!t)
 			return -EINVAL;

 		access_idx = spec->raw_spec[i];
 		acc = &spec->spec[spec->len];

 		if (btf_is_composite(t)) {
 			const struct btf_member *m;
 			__u32 bit_offset;

 			if (access_idx >= btf_vlen(t))
 				return -EINVAL;

 			bit_offset = btf_member_bit_offset(t, access_idx);
 			spec->bit_offset += bit_offset;

 			m = btf_members(t) + access_idx;
 			if (m->name_off) {
 				name = btf__name_by_offset(btf, m->name_off);
 				if (str_is_empty(name))
 					return -EINVAL;

 				acc->type_id = id;
 				acc->idx = access_idx;
 				acc->name = name;
 				spec->len++;
 			}

 			id = m->type;
 		} else if (btf_is_array(t)) {
 			const struct btf_array *a = btf_array(t);
 			bool flex;

 			t = skip_mods_and_typedefs(btf, a->type, &id);
 			if (!t)
 				return -EINVAL;

 			flex = is_flex_arr(btf, acc - 1, a);
 			if (!flex && access_idx >= a->nelems)
 				return -EINVAL;

 			spec->spec[spec->len].type_id = id;
 			spec->spec[spec->len].idx = access_idx;
 			spec->len++;

 			sz = btf__resolve_size(btf, id);
 			if (sz < 0)
 				return sz;
 			spec->bit_offset += access_idx * sz * 8;
 		} else {
 			pr_warn("prog '%s': relo for [%u] %s (at idx %d) captures type [%d] of unexpected kind %s\n",
 				prog_name, relo->type_id, spec_str, i, id, btf_kind_str(t));
 			return -EINVAL;
 		}
 	}

 	return 0;
 }



